  "warehouse.scanner.help.title": "Installation & FAQ",
  "warehouse.scanner.help.install.title": "Installing a scanner",
  "warehouse.scanner.help.install.keyboard": "USB scanners: just plug it in. Windows recognizes it automatically as a keyboard — no driver needed.",
  "warehouse.scanner.help.install.serial": "Serial / COM-port scanners: install the manufacturer's Windows driver first. Once installed, the wizard's device picker will be able to find it.",
  "warehouse.scanner.help.faq.wrongField.q": "The scanner types into the wrong field",
  "warehouse.scanner.help.faq.wrongField.a": "Click into the field you want the scan to land in before scanning — a USB scanner sends keystrokes to whatever currently has focus, exactly like a keyboard.",
  "warehouse.scanner.help.faq.nothingHappens.q": "Nothing happens when I scan",
  "warehouse.scanner.help.faq.nothingHappens.a": "Check for the scanner's own beep or light confirming a successful read, then re-run the setup wizard's test step.",
  "warehouse.scanner.help.faq.notListed.q": "My scanner doesn't appear in the device picker",
  "warehouse.scanner.help.faq.notListed.a": "It's most likely a standard keyboard-style scanner — choose that option instead. If it's meant to be a Serial/COM device, install its Windows driver first.",
  "warehouse.scanner.help.faq.browser.q": "Which browser do I need?",
  "warehouse.scanner.help.faq.browser.a": "Serial/COM device detection needs Chrome or Edge. The standard USB scanner option works in any browser.",
  "warehouse.scanner.help.faq.bluetooth.q": "Does this work with a Bluetooth scanner?",
  "warehouse.scanner.help.faq.bluetooth.a": "Yes, if it pairs as a Bluetooth keyboard — set it up with Windows first, then use the standard USB scanner option here. Bluetooth Serial devices aren't supported by this wizard.",

